Author: Grzegorz Antoniak <ga@anadoxin.org>
Date:   Sun Jun 16 09:49:05 2019 +0200

    RAR5 reader: window_mask was not updated correctly

    The `window_mask` variable should be always in sync with the
    `window_size` variable.

    The commit fixes a bug in which there was one place that `window_size`
    was modified, but `window_mask` wasn't updated. This was leading to a
    SIGSEGV error, because by having wrong `window_mask`, RAR5 reader was
    accessing the memory outsize current window buffer.

    The commit also adds a test for this issue, together with OSSFuzz
    sample #15278.

diff --git a/libarchive/archive_read_support_format_rar5.c b/libarchive/archive_read_support_format_rar5.c
index 7c24627b..95579e15 100644
--- a/libarchive/archive_read_support_format_rar5.c
+++ b/libarchive/archive_read_support_format_rar5.c
@@ -1125,6 +1125,13 @@ static void init_header(struct archive_read* a) {
        a->archive.archive_format_name = "RAR5";
 }

+static void init_window_mask(struct rar5* rar) {
+       if (rar->cstate.window_size)
+               rar->cstate.window_mask = rar->cstate.window_size - 1;
+       else
+               rar->cstate.window_mask = 0;
+}
+
 enum HEADER_FLAGS {
        HFL_EXTRA_DATA = 0x0001,
        HFL_DATA = 0x0002,
@@ -1672,6 +1679,7 @@ static int process_head_file(struct archive_read* a, struct rar5* rar,
        /* Values up to 64M should fit into ssize_t on every
         * architecture. */
        rar->cstate.window_size = (ssize_t) window_size;
+       init_window_mask(rar);

        rar->file.solid = (compression_info & SOLID) > 0;
        rar->file.service = 0;
@@ -2235,10 +2243,7 @@ static int rar5_read_header(struct archive_read *a,

 static void init_unpack(struct rar5* rar) {
        rar->file.calculated_crc32 = 0;
-       if (rar->cstate.window_size)
-               rar->cstate.window_mask = rar->cstate.window_size - 1;
-       else
